const recordIdempotencyKey = `-- name: RecordIdempotencyKey :one
INSERT INTO idempotency_keys (tenant_id, operation, idempotency_key, request_fingerprint, message_id, expires_at)
VALUES ($1, $2, $3, $4, $5,
        now() + make_interval(secs => $6::double precision))
ON CONFLICT (tenant_id, operation, idempotency_key) DO UPDATE
SET request_fingerprint = EXCLUDED.request_fingerprint,
    message_id = EXCLUDED.message_id,
    created_at = now(),
    expires_at = EXCLUDED.expires_at
WHERE idempotency_keys.expires_at <= now()
RETURNING message_id
`

type RecordIdempotencyKeyParams struct {
	TenantID           pgtype.UUID
	Operation          string
	IdempotencyKey     string
	RequestFingerprint []byte
	MessageID          pgtype.UUID
	RetentionSeconds   float64
}

// Inserts the record, or replaces an expired one (an expired key is treated as new, ADR-0018).
// Returns no row if a live record exists (a concurrent request committed it first).
func (q *Queries) RecordIdempotencyKey(ctx context.Context, arg RecordIdempotencyKeyParams) (pgtype.UUID, error) {
	row := q.db.QueryRow(ctx, recordIdempotencyKey,
		arg.TenantID,
		arg.Operation,
		arg.IdempotencyKey,
		arg.RequestFingerprint,
		arg.MessageID,
		arg.RetentionSeconds,
	)
	var message_id pgtype.UUID
	err := row.Scan(&message_id)
	return message_id, err
}

