const transitionMessage = `-- name: TransitionMessage :execrows
UPDATE messages
SET status = $1, status_reason = $2, status_updated_at = now(), updated_at = now(),
    provider_id = COALESCE($3::text, provider_id)
WHERE tenant_id = $4 AND id = $5 AND status = $6
`

type TransitionMessageParams struct {
	ToStatus     string
	StatusReason *string
	ProviderID   *string
	TenantID     pgtype.UUID
	ID           pgtype.UUID
	FromStatus   string
}

// Changes the status only if the message is still in from_status (compare-and-set).
func (q *Queries) TransitionMessage(ctx context.Context, arg TransitionMessageParams) (int64, error) {
	result, err := q.db.Exec(ctx, transitionMessage,
		arg.ToStatus,
		arg.StatusReason,
		arg.ProviderID,
		arg.TenantID,
		arg.ID,
		arg.FromStatus,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
